60	/** The show's declared accessibility options ([] when none / unknown). */
61	export function showAccessibility(show) {
62	  const list = show && show.accessibility;
63	  return Array.isArray(list) ? list : [];
64	}
65	
66	/**
67	 * One pass over the catalogue: which optional facets carry any data, and the
68	 * value set for the data-driven ones.
69	 *
70	 * @returns {{accessibility: string[], hasPrice: boolean}} accessibility is the
71	 *   sorted union of declared options (empty = the facet has no data yet).
72	 */
73	export function catalogueFacets(shows) {
74	  const access = new Set();
75	  let hasPrice = false;
76	  for (const show of shows || []) {
77	    for (const a of showAccessibility(show)) access.add(a);
78	    if (!hasPrice && parsePrice(show && show.price) !== null) hasPrice = true;
79	  }
80	  return { accessibility: [...access].sort(), hasPrice };
81	}
82	
83	/**
84	 * @typedef {object} SearchFilters
85	 * @property {string|string[]} [genre]         genre label(s); several = any of them
86	 * @property {string|string[]} [subgenre]      subgenre label(s) (matched in show.subgenres)
87	 * @property {string|string[]} [accessibility] enum value(s) the show must declare
88	 * @property {string|string[]} [venue]         venue code(s) — `show.venue`, so every
89	 *                                    room of a venue counts as that venue
90	 * @property {number} [maxAge]        highest admitted minimum age (inclusive):
91	 *                                    2 excludes nothing rated above 2; unknown excluded
92	 * @property {"free"|number} [price]  "free", or a cap in pounds (inclusive);
93	 *                                    unknown-price shows excluded either way
94	 *
95	 * The four label facets take one value or many. Many are OR'd — the UI offers
96	 * them as checkbox lists, where ticking a second box widens the search — while
97	 * separate facets are AND'd.
98	 */
99	
100	/** A facet's values as a list: "" / undefined / [] all mean "not set". */
101	function facetValues(v) {
102	  if (Array.isArray(v)) return v.filter(Boolean);
103	  return v ? [v] : [];
104	}
105	
106	/** True when any filter field is set (i.e. filtering would narrow the list). */
107	export function hasActiveFilters(filters) {
108	  const f = filters || {};
109	  return (
110	    facetValues(f.genre).length > 0 ||
111	    facetValues(f.subgenre).length > 0 ||
112	    facetValues(f.accessibility).length > 0 ||
113	    facetValues(f.venue).length > 0 ||
114	    typeof f.maxAge === "number" ||
115	    f.price === "free" ||
116	    typeof f.price === "number"
117	  );
118	}
119	
120	/** The shows passing every set filter (see SearchFilters for the semantics). */
121	export function filterShows(shows, filters) {
122	  const f = filters || {};
123	  const genres = facetValues(f.genre);
124	  const subgenres = facetValues(f.subgenre);
125	  const access = facetValues(f.accessibility);
126	  const venues = facetValues(f.venue);
127	  return (shows || []).filter((show) => {
128	    if (genres.length && !genres.includes(show.genre)) return false;
129	    if (subgenres.length && !subgenres.some((s) => (show.subgenres || []).includes(s))) return false;
130	    if (access.length && !access.some((a) => showAccessibility(show).includes(a))) return false;
131	    if (venues.length && !venues.includes(String(show.venue))) return false;
132	    if (typeof f.maxAge === "number") {
133	      const age = ageLimitYears(show);
134	      if (age === null || age > f.maxAge) return false;
135	    }
136	    if (f.price === "free") {
137	      if (showPrice(show) !== 0) return false;
138	    } else if (typeof f.price === "number") {
139	      const price = showPrice(show);
140	      if (price === null || price > f.price) return false;
141	    }
142	    return true;
143	  });
144	}

