.seg-count { display: block; font-size: 0.72rem; font-weight: 700; color: #9aa39a; font-variant-numeric: tabular-nums; line-height: 1.2; }
.seg-btn.is-active .seg-count { color: rgba(255, 255, 255, 0.82); }
.seg-count:empty { display: none; }
.seg-btn:focus-visible { outline: 3px solid var(--gold); outline-offset: 2px; }
