// Drive the Now page: open the $ price chip, read its options and counts,
// pick a cap, and confirm the rendered list actually narrows to that budget.
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium/chrome-linux/chrome" });
const page = await browser.newPage({ viewport: { width: 1280, height: 1000 } });
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));
page.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text()); });

await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8123/index.html", { waitUntil: "networkidle" });
await page.waitForTimeout(1500);

// Open the price chip.
await page.click('[data-panel="pricePanel"]');
await page.waitForTimeout(400);

const options = await page.$$eval("#priceOptions .seg-btn", (bs) =>
  bs.map((b) => ({
    value: b.dataset.price,
    label: b.textContent.replace(/\d+$/, "").trim(),
    aria: b.getAttribute("aria-label"),
  }))
);
console.log("PRICE OPTIONS:", JSON.stringify(options, null, 1));

await page.screenshot({ path: "/tmp/claude-0/-home-user-EdFringeNow/8ed0b97d-5b51-57ca-acb1-c55a4c0472cf/scratchpad/price-chip.png" });

// Pick "Up to £20" and read back what the list shows.
await page.click('#priceOptions .seg-btn[data-price="20"]');
await page.waitForTimeout(600);
const chipValue = await page.textContent('[data-value="price"]');
console.log("CHIP VALUE:", chipValue);

const listed = await page.$$eval(".si-walk", (els) => els.map((e) => e.textContent.trim()));
console.log("LISTED (first 12):", JSON.stringify(listed.slice(0, 12), null, 1));
console.log("LISTED COUNT:", listed.length);

await page.screenshot({ path: "/tmp/claude-0/-home-user-EdFringeNow/8ed0b97d-5b51-57ca-acb1-c55a4c0472cf/scratchpad/price-filtered.png", fullPage: false });

console.log("PAGE ERRORS:", errors.length ? errors : "none");
await browser.close();

