// pipeline (day file -> adaptShow -> matchesPrice -> list render) is, and it
// runs for real.
import { chromium } from "/opt/node22/lib/node_modules/playwright/index.mjs";

const SHOT = "/tmp/claude-0/-home-user-EdFringeNow/8ed0b97d-5b51-57ca-acb1-c55a4c0472cf/scratchpad";
const browser = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium-1194/chrome-linux/chrome" });
const page = await browser.newPage({ viewport: { width: 1240, height: 1100 } });
const errors = [];
page.on("pageerror", (e) => errors.push("pageerror: " + String(e)));

await page.route("**/unpkg.com/**", (route) => {
  if (route.request().url().endsWith(".css")) return route.fulfill({ contentType: "text/css", body: "" });
  route.fulfill({ contentType: "application/javascript", body: `
    const chain = new Proxy(function () {}, {
      get: (t, k) => (k === Symbol.toPrimitive || k === "toString" ? () => "stub" : chain),
      apply: () => chain,
      construct: () => chain,
    });
    window.L = chain;
  ` });
});
await page.route("**/fonts.googleapis.com/**", (r) => r.fulfill({ contentType: "text/css", body: "" }));

await page.goto("http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:8123/index.html", { waitUntil: "domcontentloaded" });
